// Characterization tests: pin CURRENT behaviour of order totals, bugs included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 100, D: 0.99, E: 100.01, F: 33.33, G: 19.99 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (items) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ items }),
})

const cases = [
  // [description, items, expected total]
  ['single item, no discount', [{ sku: 'A', qty: 1 }], 10],
  ['multiple lines are summed', [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }], 71],
  ['fractional total is floored, not rounded', [{ sku: 'D', qty: 1 }], 0],
  ['fractional 70.5 floors to 70', [{ sku: 'B', qty: 1 }, { sku: 'A', qty: 4 }, { sku: 'D', qty: 5 }].slice(0, 0).concat([{ sku: 'A', qty: 4 }, { sku: 'B', qty: 1 }, { sku: 'D', qty: 0 }]), 65],
  ['exactly 100 gets NO discount (threshold is strictly >100)', [{ sku: 'C', qty: 1 }], 100],
  ['100.01 gets 10% off then floored (90.009 -> 90)', [{ sku: 'E', qty: 1 }], 90],
  ['200 -> 180', [{ sku: 'C', qty: 2 }], 180],
  ['1000 -> 900', [{ sku: 'C', qty: 10 }], 900],
  ['discount applied once on whole order, no tiers for larger orders', [{ sku: 'C', qty: 100 }], 9000],
  ['discounted fraction floored (3*33.33*2=199.98 -> 179.982 -> 179)', [{ sku: 'F', qty: 6 }], 179],
  ['floating point: 19.99*7=139.93 -> 125.937 -> 125', [{ sku: 'G', qty: 7 }], 125],
  ['qty 0 contributes nothing', [{ sku: 'A', qty: 0 }], 0],
]

for (const [name, items, total] of cases) {
  test(name, async () => {
    const res = await post(items)
    assert.equal(res.status, 201)
    const order = await res.json()
    assert.equal(order.total, total)
    assert.deepEqual(order.items, items)
  })
}

